from typing import List
class Solution:
    def maxProduct(self, nums: List[int]) -> int:
        curMax = curMin = ans = nums[0]
        for x in nums[1:]:
            if x < 0:
                curMax, curMin = curMin, curMax
            curMax = max(x, curMax * x)
            curMin = min(x, curMin * x)
            if curMax > ans:
                ans = curMax
        return ans

